svg.script:
// Variables de estado
let powerOn = false;
let switch1On = false;
let switch2Pressed = false;
let animationInterval;

// Elementos del DOM
const powerBtn = document.getElementById('power-btn');
const powerBtnText = powerBtn.nextElementSibling;
const statusLED = document.getElementById('status-led');
const circuitStatus = document.getElementById('circuit-status');

const switch1Lever = document.getElementById('switch1-lever');
const switch1Status = document.getElementById('switch1-status');

const switch2Button = document.getElementById('switch2-button');
const switch2Status = document.getElementById('switch2-status');

const bulbElement = document.getElementById('bulb-element');
const bulbBase = document.getElementById('bulb-base');
const bulbStatus = document.getElementById('bulb-status');

// Funciones de utilidad
function updateCircuit() {
    // Verificar si el circuito está completo
    const circuitComplete = switch1On && switch2Pressed;

    // Actualizar bombilla
    if (powerOn && circuitComplete) {
        bulbElement.classList.remove('bulb-off');
        bulbElement.classList.add('bulb-on');
        bulbBase.classList.remove('bulb-off');
        bulbBase.classList.add('bulb-on');
        bulbStatus.textContent = 'ENCENDIDA';
        bulbStatus.setAttribute('fill', '#2ecc71');

        // Mostrar corriente
        document.querySelectorAll('#current1, #current2, #current3, #current4, #current5').forEach(el => {
            el.style.display = 'inline';
        });

        // Iniciar animación de corriente
        if (!animationInterval) {
            let offset = 0;
            animationInterval = setInterval(() => {
                offset = (offset + 1) % 20;
                document.querySelectorAll('.wire-active').forEach(el => {
                    el.style.strokeDasharray = '10,10';
                    el.style.strokeDashoffset = -offset;
                });
            }, 100);
        }
    } else {
        bulbElement.classList.remove('bulb-on');
        bulbElement.classList.add('bulb-off');
        bulbBase.classList.remove('bulb-on');
        bulbBase.classList.add('bulb-off');
        bulbStatus.textContent = 'APAGADA';
        bulbStatus.setAttribute('fill', '#e74c3c');

        // Ocultar corriente
        document.querySelectorAll('.wire-active').forEach(el => {
            el.style.display = 'none';
        });

        // Detener animación
        if (animationInterval) {
            clearInterval(animationInterval);
            animationInterval = null;
        }
    }

    // Actualizar estado del circuito
    if (!powerOn) {
        circuitStatus.textContent = 'APAGADO';
        statusLED.setAttribute('fill', '#e74c3c');
    } else if (!switch1On || !switch2Pressed) {
        circuitStatus.textContent = 'INCOMPLETO';
        statusLED.setAttribute('fill', '#f1c40f');
    } else {
        circuitStatus.textContent = 'FUNCIONANDO';
        statusLED.setAttribute('fill', '#2ecc71');
    }
}

// Event Listeners
powerBtn.addEventListener('click', function() {
    powerOn = !powerOn;
    if (powerOn) {
        this.setAttribute('fill', '#e74c3c');
        powerBtnText.textContent = 'APAGAR';
    } else {
        this.setAttribute('fill', '#2ecc71');
        powerBtnText.textContent = 'ENCENDER';
    }
    updateCircuit();
});

// Interruptor de palanca
document.getElementById('switch1').addEventListener('click', function() {
    if (!powerOn) return;

    switch1On = !switch1On;
    if (switch1On) {
        switch1Lever.setAttribute('transform', 'rotate(45, 0, 30)');
        switch1Status.textContent = 'ENCENDIDO';
        switch1Status.setAttribute('fill', '#2ecc71');
    } else {
        switch1Lever.setAttribute('transform', 'rotate(0, 0, 30)');
        switch1Status.textContent = 'APAGADO';
        switch1Status.setAttribute('fill', '#e74c3c');
    }
    updateCircuit();
});

// Pulsador NA
switch2Button.addEventListener('mousedown', function() {
    if (!powerOn) return;

    switch2Pressed = true;
    switch2Status.textContent = 'PRESIONADO';
    switch2Status.setAttribute('fill', '#2ecc71');
    this.setAttribute('r', '8');
    updateCircuit();
});

switch2Button.addEventListener('mouseup', function() {
    if (!powerOn) return;

    switch2Pressed = false;
    switch2Status.textContent = 'SUÉLTAME';
    switch2Status.setAttribute('fill', '#e74c3c');
    this.setAttribute('r', '12');
    updateCircuit();
});

switch2Button.addEventListener('mouseleave', function() {
    if (switch2Pressed) {
        switch2Pressed = false;
        switch2Status.textContent = 'SUÉLTAME';
        switch2Status.setAttribute('fill', '#e74c3c');
        this.setAttribute('r', '12');
        updateCircuit();
    }
});

// Inicialización
updateCircuit();
